SELECT cfg.device_code AS deviceCode, cfg.algorithm_code AS algorithmCode, inf.algorithm_name AS algorithmName FROM vm_order_algorithm_config cfg LEFT JOIN vm_order_algorithms inf ON cfg.order_code = inf.order_code and cfg.algorithm_code = inf.algorithm_code AND inf.delete_flag = '0' WHERE cfg.delete_flag = 0 AND cfg.order_code = #{orderCode}
AND cfg.device_code IN
#{item}
group by cfg.device_code,cfg.algorithm_code
